1	import { charNotIn, createRegExp, exactly, global, oneOrMore } from 'magic-regexp';
2	import { parseQuery } from 'ufo';
3	import { canonicalize, sha256 } from '../../../core/src/receipts/canonicalize.ts';
4	
5	/**
6	 * Frozen synthetic Memos API projection.
7	 *
8	 * The retained Memos build is session-gated: `pages/Home.tsx` calls
9	 * `GET /api/user/me` on mount and replaces history with `/signin` whenever that
10	 * call does not yield a user, so nothing behind the gate can be witnessed until
11	 * a session exists. This module is the deterministic state machine that stands
12	 * in for the Go backend the pinned revision talks to: it answers exactly the
13	 * same-origin `/api` surface the pinned `web/src` reaches (enumerated in
14	 * `evidence/runs/react-memos-v0-1-3/t006-api-surface.json`), it serves only
15	 * data authored for this fixture, it holds every record in memory, and it never
16	 * contacts anything.
17	 *
18	 * Three properties make it evidence rather than a mock:
19	 *
20	 * 1. It fails closed. A path the pinned client never calls is refused with a
21	 *    named refusal instead of inheriting a generous default, and an enumerated
22	 *    endpoint this projection deliberately does not project is refused with a
23	 *    DIFFERENT named refusal, so "unknown to the application" and "known and
24	 *    withheld" can never be confused in the ledger.
25	 * 2. Every transport decision is ledgered — method, path, query, endpoint id,
26	 *    decision, status, the session state the decision left in force, and
27	 *    digests of the request and response bytes.
28	 * 3. Its behavior is frozen by digest. `MEMOS_PROJECTION_BEHAVIOR_DIGEST` is
29	 *    taken over the replay of a fixed transcript, so a journey cannot drift the
30	 *    projection's answers without the digest test failing first.
31	 *
32	 * The session is projection-local state, not a cookie: the loopback API seam
33	 * carries method, path, query and body but no headers, so this projection
34	 * records the session established by `/api/auth/login` or `/api/auth/signup`
35	 * inside the per-run projection instance. One browser talks to one projection
36	 * for one run, so the observable gate behaviour is the application's own.
37	 */
38	export const MEMOS_PROJECTION_LABEL = 'synthetic-fixture-evidence-data' as const;
39	
40	/** The pinned revision whose `web/src` this projection answers. */
41	export const MEMOS_PINNED_REVISION = '565fe0cc567c02deb59fc04830df707ea7476d52' as const;
42	
43	export type MemosRowStatus = 'NORMAL' | 'ARCHIVED';
44	export type MemosUserRole = 'OWNER' | 'USER';
45	
46	export type MemosUser = {
47		id: number;
48		createdTs: number;
49		updatedTs: number;
50		rowStatus: MemosRowStatus;
51		role: MemosUserRole;
52		email: string;
53		name: string;
54		openId: string;
55	};
56	
57	export type MemosMemo = {
58		id: number;
59		creatorId: number;
60		createdTs: number;
61		updatedTs: number;
62		rowStatus: MemosRowStatus;
63		content: string;
64		pinned: boolean;
65	};
66	
67	export type MemosShortcut = {
68		id: number;
69		creatorId: number;
70		rowStatus: MemosRowStatus;
71		createdTs: number;
72		updatedTs: number;
73		title: string;
74		payload: string;
75	};
76	
77	/**
78	 * The projection's synthetic seed, committed alongside the fixture as
79	 * `fixtures/react-memos-v0-1-3/witness-projection-seed.json`.
80	 *
81	 * Timestamps are UNIX seconds because that is what the pinned client expects:
82	 * every service multiplies `createdTs` by 1000 before it renders.
83	 */
84	export type MemosSeed = {
85		label: string;
86		users: readonly MemosUser[];
87		credentials: readonly { userId: number; password: string }[];
88		memos: readonly MemosMemo[];
89		shortcuts: readonly MemosShortcut[];
90		profile: { mode: string; version: string };
91	};
92	
93	const seconds = (iso: string): number => Math.floor(Date.parse(iso) / 1000);
94	
95	/**
96	 * The site owner. The address is on `.invalid`, which can never resolve, and
97	 * the passphrase below is labelled synthetic in its own value: neither is a
98	 * credential for anything that exists.
99	 */
100	const OWNER: MemosUser = {
101		id: 1,
102		createdTs: seconds('2026-08-01T09:00:00.000Z'),
103		updatedTs: seconds('2026-08-01T09:00:00.000Z'),
104		rowStatus: 'NORMAL',
105		role: 'OWNER',
106		email: 'owner@versionless-evidence.invalid',
107		name: 'owner@versionless-evidence.invalid',
108		openId: 'synthetic-open-id-owner',
109	};
110	
111	export const MEMOS_OWNER_PASSWORD = 'synthetic-owner-passphrase' as const;
112	
113	const memo = (
114		id: number,
115		content: string,
116		createdAt: string,
117		rowStatus: MemosRowStatus = 'NORMAL',
118		pinned = false,
119	): MemosMemo => ({
120		id,
121		creatorId: OWNER.id,
122		createdTs: seconds(createdAt),
123		updatedTs: seconds(createdAt),
124		rowStatus,
125		content,
126		pinned,
127	});
128	
129	/**
130	 * The seeded memos.
131	 *
132	 * Every tag is written as `#tag ` — a hash, a token, then a space — because the
133	 * pinned client's own `TAG_REG` (`/#(.+?) /g`) only recognises a tag that a
134	 * space closes. Deriving `/api/tag` under the same rule keeps the tag list the
135	 * sidebar renders identical to the tags the client's filter can match.
136	 */
137	export const MEMOS_SEED: MemosSeed = Object.freeze({
138		label: MEMOS_PROJECTION_LABEL,
139		users: Object.freeze([OWNER]),
140		credentials: Object.freeze([{ userId: OWNER.id, password: MEMOS_OWNER_PASSWORD }]),
141		memos: Object.freeze([
142			memo(
143				1,
144				'Pinned the era baseline for the retained build. #evidence tracked in the run ledger.',
145				'2026-08-02T09:00:00.000Z',
146				'NORMAL',
147				true,
148			),
149			memo(
150				2,
151				'The origin bundler is itself Vite, six majors back. #migration notes stay with the lane.',
152				'2026-08-03T09:00:00.000Z',
153			),
154			memo(
155				3,
156				'Config translation replaced the removed client APIs. #migration #evidence both apply.',
157				'2026-08-04T09:00:00.000Z',
158			),
159			memo(
160				4,
161				'Superseded draft kept only to prove restore from the recycle bin. #archive holds it.',
162				'2026-08-05T09:00:00.000Z',
163				'ARCHIVED',
164			),
165		]),
166		shortcuts: Object.freeze([
167			{
168				id: 1,
169				creatorId: OWNER.id,
170				rowStatus: 'ARCHIVED',
171				createdTs: seconds('2026-08-06T09:00:00.000Z'),
172				updatedTs: seconds('2026-08-06T09:00:00.000Z'),
173				title: 'Evidence',
174				payload:
175					'[{"type":"TAG","value":{"operator":"CONTAIN","value":"evidence"},"relation":"AND"}]',
176			},
177			{
178				id: 2,
179				creatorId: OWNER.id,
180				rowStatus: 'NORMAL',
181				createdTs: seconds('2026-08-07T09:00:00.000Z'),
182				updatedTs: seconds('2026-08-07T09:00:00.000Z'),
183				title: 'Migration',
184				payload:
185					'[{"type":"TAG","value":{"operator":"CONTAIN","value":"migration"},"relation":"AND"}]',
186			},
187		] as readonly MemosShortcut[]),
188		profile: Object.freeze({ mode: 'prod', version: '0.1.3' }),
189	});
190	
191	/** sha256 over the canonicalized seed, so the committed fixture copy cannot drift. */
192	export const memosSeedDigest = (): string => sha256(canonicalize(MEMOS_SEED));
193	
194	/**
195	 * The mutation clock. Records the projection mints get timestamps from a fixed
196	 * origin advanced one step per mutation, so two runs of the same journey
197	 * produce identical records without reading the wall clock.
198	 */
199	const MUTATION_CLOCK_ORIGIN_SECONDS = seconds('2026-08-09T00:00:00.000Z');
200	const MUTATION_CLOCK_STEP_SECONDS = 60;
201	
202	const MEMO_TAG = createRegExp(
203		exactly('#'),
204		oneOrMore(charNotIn(' \n\t#')).groupedAs('tag'),
205		exactly(' '),
206		[global],
207	);
208	
209	/** Tags the pinned client's own `TAG_REG` would find in this content. */
210	export function memosTagsInContent(content: string): string[] {
211		const found: string[] = [];
212		for (const match of content.matchAll(MEMO_TAG)) {
213			const tag = match.groups?.tag;
214			if (tag !== undefined && tag.length > 0 && !found.includes(tag)) found.push(tag);
215		}
216		return found;
217	}
218	
219	export type MemosApiRequest = {
220		method: string;
221		pathname: string;
222		search: string;
223		body: Buffer;
224	};
225	
226	export type MemosApiResponse = { status: number; contentType: string; body: Buffer };
227	
228	export type MemosProjectionDecision =
229		| 'served'
230		| 'refused-unknown'
231		| 'refused-unprojected'
232		| 'declined-non-api';
233	
234	export type MemosProjectionLedgerRecord = {
235		sequence: number;
236		method: string;
237		pathname: string;
238		search: string;
239		endpoint: string | null;
240		decision: MemosProjectionDecision;
241		status: number | null;
242		/** Whether a session stood open once this decision had been taken. */
243		authenticated: boolean;
244		requestSha256: string;
245		responseSha256: string | null;
246	};
247	
248	export type MemosProjection = {
249		api(request: MemosApiRequest): Promise<MemosApiResponse | null>;
250		ledger(): MemosProjectionLedgerRecord[];
251		sessionUserId(): number | null;
252		memos(): MemosMemo[];
253		shortcuts(): MemosShortcut[];
254		users(): MemosUser[];
255	};
256	
257	/**
258	 * The endpoints this projection answers, keyed by the ledger id it records.
259	 * `POST /api/resource` is enumerated in the pinned client and deliberately NOT
260	 * projected: nothing in the journey surface uploads a file, and answering an
261	 * upload would mean inventing a resource pipeline whose bytes no witness ever
262	 * sees.
263	 */
264	export const MEMOS_PROJECTED_ENDPOINTS = Object.freeze([
265		'status',
266		'auth.login',
267		'auth.signup',
268		'auth.logout',
269		'user.create',
270		'user.list',
271		'user.me.get',
272		'user.me.patch',
273		'memo.list',
274		'memo.create',
275		'memo.patch',
276		'memo.organizer',
277		'memo.delete',
278		'tag.list',
279		'shortcut.list',
280		'shortcut.create',
281		'shortcut.patch',
282		'shortcut.delete',
283	] as const);
284	
285	export const MEMOS_UNPROJECTED_ENDPOINTS = Object.freeze([
286		{
287			endpoint: 'resource.upload',
288			method: 'POST',
289			path: '/api/resource',
290			reason:
291				'no journey uploads a file; projecting an upload would mean inventing a resource ' +
292				'pipeline and a `/h/r/:id/:filename` byte stream that no witness observes',
293		},
294	] as const);
295	
296	function json(value: unknown, status = 200): MemosApiResponse {
297		return {
298			status,
299			contentType: 'application/json',
300			body: Buffer.from(JSON.stringify(value), 'utf8'),
301		};
302	}
303	
304	const envelope = (data: unknown, status = 200): MemosApiResponse => json({ data }, status);
305	
306	const failure = (status: number, error: string, message: string): MemosApiResponse =>
307		json({ error, message }, status);
308	
309	const unknownPath = (method: string, pathname: string): MemosApiResponse =>
310		failure(
311			404,
312			'unknown-endpoint',
313			`Memos synthetic projection refuses an endpoint the pinned client never calls: ${method} ${pathname}`,
314		);
315	
316	const unprojectedPath = (endpoint: string, reason: string): MemosApiResponse =>
317		failure(
318			501,
319			'unprojected-endpoint',
320			`Memos synthetic projection withholds the enumerated endpoint ${endpoint}: ${reason}`,
321		);
322	
323	function parsedBody(body: Buffer): Record<string, unknown> {
324		if (body.length === 0) return {};
325		const parsed: unknown = JSON.parse(body.toString('utf8'));
326		if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed))
327			throw new Error('Memos synthetic projection requires a JSON object body');
328		return parsed as Record<string, unknown>;
329	}
330	
331	const stringField = (source: Record<string, unknown>, key: string): string | null => {
332		const value = source[key];
333		return typeof value === 'string' ? value : null;
334	};
335	
336	const queryValue = (query: Record<string, string | string[]>, key: string): string | null => {
337		const value = query[key];
338		if (typeof value === 'string') return value;
339		return Array.isArray(value) && typeof value[0] === 'string' ? value[0] : null;
340	};
341	
342	const numericSuffix = (pathname: string, prefix: string, suffix = ''): number | null => {
343		if (!pathname.startsWith(prefix) || !pathname.endsWith(suffix)) return null;
344		const raw = pathname.slice(prefix.length, pathname.length - suffix.length);
345		if (raw.length === 0 || raw.split('').some((digit) => digit < '0' || digit > '9')) return null;
346		return Number.parseInt(raw, 10);
347	};
348	
349	type Handled = { endpoint: string; response: MemosApiResponse };
350	
351	/**
352	 * One projection instance. `createMemosProjection()` is called once per run by
353	 * the loopback seam, so every run starts from the frozen seed rather than
354	 * inheriting another run's mutations.
355	 */
356	export function createMemosProjection(): MemosProjection {
357		const users: MemosUser[] = MEMOS_SEED.users.map((user) => structuredClone(user));
358		const passwords = new Map<number, string>(
359			MEMOS_SEED.credentials.map((entry) => [entry.userId, entry.password]),
360		);
361		const memos: MemosMemo[] = MEMOS_SEED.memos.map((record) => structuredClone(record));
362		const shortcuts: MemosShortcut[] = MEMOS_SEED.shortcuts.map((record) =>
363			structuredClone(record),
364		);
365		const records: MemosProjectionLedgerRecord[] = [];
366		let session: number | null = null;
367		let mutations = 0;
368		let sequence = 0;
369	
370		const tick = (): number => {
371			const stamp = MUTATION_CLOCK_ORIGIN_SECONDS + mutations * MUTATION_CLOCK_STEP_SECONDS;
372			mutations += 1;
373			return stamp;
374		};
375		const nextId = (rows: readonly { id: number }[]): number =>
376			rows.reduce((highest, row) => (row.id > highest ? row.id : highest), 0) + 1;
377		const sessionUser = (): MemosUser | null => users.find((user) => user.id === session) ?? null;
378		const owner = (): MemosUser | null => users.find((user) => user.role === 'OWNER') ?? null;
379		const byCreated = (left: { createdTs: number }, right: { createdTs: number }): number =>
380			right.createdTs - left.createdTs;
381	
382		const unauthorized = (): MemosApiResponse =>
383			failure(401, 'unauthorized', 'Memos synthetic projection has no session for this request');
384	
385		const createUser = (
386			body: Record<string, unknown>,
387			role: MemosUserRole,
388		): MemosUser | MemosApiResponse => {
389			const email = stringField(body, 'email');
390			const password = stringField(body, 'password');
391			if (email === null || email.length === 0 || password === null || password.length === 0)
392				return failure(
393					400,
394					'invalid-request',
395					'Memos synthetic projection requires email and password',
396				);
397			if (users.some((user) => user.email === email))
398				return failure(
399					400,
400					'duplicate-user',
401					`Memos synthetic projection already holds ${email}`,
402				);
403			const stamp = tick();
404			const created: MemosUser = {
405				id: nextId(users),
406				createdTs: stamp,
407				updatedTs: stamp,
408				rowStatus: 'NORMAL',
409				role,
410				email,
411				name: stringField(body, 'name') ?? email,
412				openId: `synthetic-open-id-${nextId(users)}`,
413			};
414			users.push(created);
415			passwords.set(created.id, password);
416			return created;
417		};
418	
419		const patchMe = (user: MemosUser, body: Record<string, unknown>): MemosApiResponse => {
420			const name = stringField(body, 'name');
421			const password = stringField(body, 'password');
422			if (name !== null && name.length > 0) user.name = name;
423			if (password !== null && password.length > 0) passwords.set(user.id, password);
424			if (body['resetOpenId'] === true) user.openId = `synthetic-open-id-reset-${tick()}`;
425			user.updatedTs = tick();
426			return envelope(structuredClone(user));
427		};
428	
429		const memoList = (user: MemosUser, search: string): MemosApiResponse => {
430			const rowStatus = queryValue(parseQuery(search), 'rowStatus');
431			const visible = memos
432				.filter((record) => record.creatorId === user.id)
433				.filter((record) => rowStatus === null || record.rowStatus === rowStatus)
434				.sort(byCreated);
435			return envelope(structuredClone(visible));
436		};
437	
438		const createMemo = (user: MemosUser, body: Record<string, unknown>): MemosApiResponse => {
439			const content = stringField(body, 'content');
440			if (content === null || content.trim().length === 0)
441				return failure(
442					400,
443					'invalid-request',
444					'Memos synthetic projection requires memo content',
445				);
446			const declared = body['createdTs'];
447			const stamp = typeof declared === 'number' ? declared : tick();
448			const created: MemosMemo = {
449				id: nextId(memos),
450				creatorId: user.id,
451				createdTs: stamp,
452				updatedTs: stamp,
453				rowStatus: 'NORMAL',
454				content,
455				pinned: false,
456			};
457			memos.push(created);
458			return envelope(structuredClone(created));
459		};
460	
461		const ownedMemo = (user: MemosUser, id: number): MemosMemo | null =>
462			memos.find((record) => record.id === id && record.creatorId === user.id) ?? null;
463	
464		const patchMemo = (
465			user: MemosUser,
466			id: number,
467			body: Record<string, unknown>,
468		): MemosApiResponse => {
469			const record = ownedMemo(user, id);
470			if (record === null)
471				return failure(404, 'not-found', `Memos synthetic projection holds no memo ${id}`);
472			const content = stringField(body, 'content');
473			const rowStatus = stringField(body, 'rowStatus');
474			if (content !== null) record.content = content;
475			if (rowStatus === 'NORMAL' || rowStatus === 'ARCHIVED') record.rowStatus = rowStatus;
476			record.updatedTs = tick();
477			return envelope(structuredClone(record));
478		};
479	
480		const organizeMemo = (
481			user: MemosUser,
482			id: number,
483			body: Record<string, unknown>,
484		): MemosApiResponse => {
485			const record = ownedMemo(user, id);
486			if (record === null)
487				return failure(404, 'not-found', `Memos synthetic projection holds no memo ${id}`);
488			if (typeof body['pinned'] !== 'boolean')
489				return failure(
490					400,
491					'invalid-request',
492					'Memos synthetic projection requires a pinned flag',
493				);
494			record.pinned = body['pinned'];
495			record.updatedTs = tick();
496			return envelope(structuredClone(record));
497		};
498	
499		const deleteMemo = (user: MemosUser, id: number): MemosApiResponse => {
500			const index = memos.findIndex((record) => record.id === id && record.creatorId === user.id);
501			if (index === -1)
502				return failure(404, 'not-found', `Memos synthetic projection holds no memo ${id}`);
503			memos.splice(index, 1);
504			return envelope(true);
505		};
506	
507		/** Tags of the session user's live memos, deduplicated and lexicographically ordered. */
508		const tagList = (user: MemosUser): MemosApiResponse => {
509			const tags = new Set<string>();
510			for (const record of memos)
511				if (record.creatorId === user.id && record.rowStatus === 'NORMAL')
512					for (const tag of memosTagsInContent(record.content)) tags.add(tag);
513			return envelope([...tags].sort());
514		};
515	
516		const ownedShortcut = (user: MemosUser, id: number): MemosShortcut | null =>
517			shortcuts.find((record) => record.id === id && record.creatorId === user.id) ?? null;
518	
519		const createShortcut = (user: MemosUser, body: Record<string, unknown>): MemosApiResponse => {
520			const title = stringField(body, 'title');
521			const payload = stringField(body, 'payload');
522			if (title === null || title.length === 0 || payload === null || payload.length === 0)
523				return failure(
524					400,
525					'invalid-request',
526					'Memos synthetic projection requires a shortcut title and payload',
527				);
528			const stamp = tick();
529			const created: MemosShortcut = {
530				id: nextId(shortcuts),
531				creatorId: user.id,
532				rowStatus: 'NORMAL',
533				createdTs: stamp,
534				updatedTs: stamp,
535				title,
536				payload,
537			};
538			shortcuts.push(created);
539			return envelope(structuredClone(created));
540		};
541	
542		const patchShortcut = (
543			user: MemosUser,
544			id: number,
545			body: Record<string, unknown>,
546		): MemosApiResponse => {
547			const record = ownedShortcut(user, id);
548			if (record === null)
549				return failure(404, 'not-found', `Memos synthetic projection holds no shortcut ${id}`);
550			const title = stringField(body, 'title');
551			const payload = stringField(body, 'payload');
552			const rowStatus = stringField(body, 'rowStatus');
553			if (title !== null && title.length > 0) record.title = title;
554			if (payload !== null && payload.length > 0) record.payload = payload;
555			if (rowStatus === 'NORMAL' || rowStatus === 'ARCHIVED') record.rowStatus = rowStatus;
556			record.updatedTs = tick();
557			return envelope(structuredClone(record));
558		};
559	
560		const deleteShortcut = (user: MemosUser, id: number): MemosApiResponse => {
561			const index = shortcuts.findIndex(
562				(record) => record.id === id && record.creatorId === user.id,
563			);
564			if (index === -1)
565				return failure(404, 'not-found', `Memos synthetic projection holds no shortcut ${id}`);
566			shortcuts.splice(index, 1);
567			return envelope(true);
568		};
569	
570		const login = (body: Record<string, unknown>): MemosApiResponse => {
571			const email = stringField(body, 'email');
572			const password = stringField(body, 'password');
573			const user = users.find((candidate) => candidate.email === email) ?? null;
574			if (user === null || password === null || passwords.get(user.id) !== password)
575				return failure(
576					401,
577					'unauthorized',
578					'Memos synthetic projection rejects these sign-in values',
579				);
580			session = user.id;
581			return envelope(structuredClone(user));
582		};
583	
584		/**
585		 * Signup. The pinned client only offers this button while `/api/status`
586		 * reports no owner, and it always asks for `OWNER`. The projection grants
587		 * `OWNER` only when no owner exists and otherwise records the account as a
588		 * plain `USER`, so the role in the store is a decision this projection made
589		 * rather than a role the client asserted.
590		 */
591		const signup = (body: Record<string, unknown>): MemosApiResponse => {
592			const created = createUser(body, owner() === null ? 'OWNER' : 'USER');
593			if (!('id' in created)) return created;
594			session = created.id;
595			return envelope(structuredClone(created));
596		};
597	
598		const authenticated = (handler: (user: MemosUser) => MemosApiResponse): MemosApiResponse => {
599			const user = sessionUser();
600			return user === null ? unauthorized() : handler(user);
601		};
602	
603		const handleUser = (request: MemosApiRequest, body: Buffer): Handled | null => {
604			if (request.pathname === '/api/user' && request.method === 'GET')
605				return {
606					endpoint: 'user.list',
607					response: authenticated(() => envelope(structuredClone(users))),
608				};
609			if (request.pathname === '/api/user' && request.method === 'POST')
610				return {
611					endpoint: 'user.create',
612					response: authenticated((user) => {
613						if (user.role !== 'OWNER')
614							return failure(
615								403,
616								'forbidden',
617								'Memos synthetic projection lets only the owner create members',
618							);
619						const created = createUser(parsedBody(body), 'USER');
620						return 'id' in created ? envelope(structuredClone(created)) : created;
621					}),
622				};
623			if (request.pathname === '/api/user/me' && request.method === 'GET')
624				return {
625					endpoint: 'user.me.get',
626					response: authenticated((user) => envelope(structuredClone(user))),
627				};
628			if (request.pathname === '/api/user/me' && request.method === 'PATCH')
629				return {
630					endpoint: 'user.me.patch',
631					response: authenticated((user) => patchMe(user, parsedBody(body))),
632				};
633			return null;
634		};
635	
636		const handleMemo = (request: MemosApiRequest, body: Buffer): Handled | null => {
637			if (request.pathname === '/api/memo' && request.method === 'GET')
638				return {
639					endpoint: 'memo.list',
640					response: authenticated((user) => memoList(user, request.search)),
641				};
642			if (request.pathname === '/api/memo' && request.method === 'POST')
643				return {
644					endpoint: 'memo.create',
645					response: authenticated((user) => createMemo(user, parsedBody(body))),
646				};
647			const organizerId = numericSuffix(request.pathname, '/api/memo/', '/organizer');
648			if (organizerId !== null && request.method === 'POST')
649				return {
650					endpoint: 'memo.organizer',
651					response: authenticated((user) =>
652						organizeMemo(user, organizerId, parsedBody(body)),
653					),
654				};
655			const memoId = numericSuffix(request.pathname, '/api/memo/');
656			if (memoId !== null && request.method === 'PATCH')
657				return {
658					endpoint: 'memo.patch',
659					response: authenticated((user) => patchMemo(user, memoId, parsedBody(body))),
660				};
661			if (memoId !== null && request.method === 'DELETE')
662				return {
663					endpoint: 'memo.delete',
664					response: authenticated((user) => deleteMemo(user, memoId)),
665				};
666			return null;
667		};
668	
669		const handleShortcut = (request: MemosApiRequest, body: Buffer): Handled | null => {
670			if (request.pathname === '/api/shortcut' && request.method === 'GET')
671				return {
672					endpoint: 'shortcut.list',
673					response: authenticated((user) =>
674						envelope(
675							structuredClone(
676								shortcuts
677									.filter((record) => record.creatorId === user.id)
678									.sort(byCreated),
679							),
680						),
681					),
682				};
683			if (request.pathname === '/api/shortcut' && request.method === 'POST')
684				return {
685					endpoint: 'shortcut.create',
686					response: authenticated((user) => createShortcut(user, parsedBody(body))),
687				};
688			const shortcutId = numericSuffix(request.pathname, '/api/shortcut/');
689			if (shortcutId !== null && request.method === 'PATCH')
690				return {
691					endpoint: 'shortcut.patch',
692					response: authenticated((user) =>
693						patchShortcut(user, shortcutId, parsedBody(body)),
694					),
695				};
696			if (shortcutId !== null && request.method === 'DELETE')
697				return {
698					endpoint: 'shortcut.delete',
699					response: authenticated((user) => deleteShortcut(user, shortcutId)),
700				};
701			return null;
702		};
703	
704		const handle = (request: MemosApiRequest): Handled => {
705			const body = request.body;
706			if (request.pathname === '/api/status' && request.method === 'GET') {
707				const siteOwner = owner();
708				return {
709					endpoint: 'status',
710					response: envelope({
711						...(siteOwner === null ? {} : { owner: structuredClone(siteOwner) }),
712						profile: { ...MEMOS_SEED.profile },
713					}),
714				};
715			}
716			if (request.pathname === '/api/auth/login' && request.method === 'POST')
717				return { endpoint: 'auth.login', response: login(parsedBody(body)) };
718			if (request.pathname === '/api/auth/signup' && request.method === 'POST')
719				return { endpoint: 'auth.signup', response: signup(parsedBody(body)) };
720			if (request.pathname === '/api/auth/logout' && request.method === 'POST') {
721				session = null;
722				return { endpoint: 'auth.logout', response: envelope(true) };
723			}
724			if (request.pathname === '/api/tag' && request.method === 'GET')
725				return { endpoint: 'tag.list', response: authenticated((user) => tagList(user)) };
726			const withheld = MEMOS_UNPROJECTED_ENDPOINTS.find(
727				(entry) => entry.path === request.pathname && entry.method === request.method,
728			);
729			if (withheld !== undefined)
730				return {
731					endpoint: withheld.endpoint,
732					response: unprojectedPath(withheld.endpoint, withheld.reason),
733				};
734			const handled =
735				handleUser(request, body) ?? handleMemo(request, body) ?? handleShortcut(request, body);
736			return (
737				handled ?? {
738					endpoint: '',
739					response: unknownPath(request.method, request.pathname),
740				}
741			);
742		};
743	
744		const record = (
745			request: MemosApiRequest,
746			endpoint: string | null,
747			decision: MemosProjectionDecision,
748			response: MemosApiResponse | null,
749		): void => {
750			sequence += 1;
751			records.push({
752				sequence,
753				method: request.method,
754				pathname: request.pathname,
755				search: request.search,
756				endpoint,
757				decision,
758				status: response?.status ?? null,
759				authenticated: session !== null,
760				requestSha256: sha256(request.body),
761				responseSha256: response === null ? null : sha256(response.body),
762			});
763		};
764	
765		const api = async (request: MemosApiRequest): Promise<MemosApiResponse | null> => {
766			if (!request.pathname.startsWith('/api/')) {
767				record(request, null, 'declined-non-api', null);
768				return null;
769			}
770			const handled = handle(request);
771			const endpoint = handled.endpoint.length === 0 ? null : handled.endpoint;
772			const decision: MemosProjectionDecision =
773				endpoint === null
774					? 'refused-unknown'
775					: handled.response.status === 501
776						? 'refused-unprojected'
777						: 'served';
778			record(request, endpoint, decision, handled.response);
779			return handled.response;
780		};
781	
782		return {
783			api,
784			ledger: () => records.map((entry) => ({ ...entry })),
785			sessionUserId: () => session,
786			memos: () => structuredClone(memos),
787			shortcuts: () => structuredClone(shortcuts),
788			users: () => structuredClone(users),
789		};
790	}
791	
792	export type MemosTranscriptStep = {
793		method: string;
794		pathname: string;
795		search?: string;
796		body?: unknown;
797	};
798	
799	/**
800	 * The frozen behaviour transcript.
801	 *
802	 * It walks the whole journey surface the enumeration records — the signed-out
803	 * gate, the sign-in that opens it, the memo list, a memo written and edited,
804	 * archive and restore, the derived tag list, a shortcut created, the settings
805	 * patch, sign-out and the gate closing again — plus both refusals. Replaying it
806	 * through a fresh projection is what `MEMOS_PROJECTION_BEHAVIOR_DIGEST` covers.
807	 */
808	export const MEMOS_PROJECTION_BEHAVIOR_TRANSCRIPT: readonly MemosTranscriptStep[] = Object.freeze([
809		{ method: 'GET', pathname: '/index.html' },
810		{ method: 'GET', pathname: '/api/status' },
811		{ method: 'GET', pathname: '/api/user/me' },
812		{
813			method: 'POST',
814			pathname: '/api/auth/login',
815			body: { email: OWNER.email, password: 'wrong-synthetic-passphrase' },
816		},
817		{
818			method: 'POST',
819			pathname: '/api/auth/login',
820			body: { email: OWNER.email, password: MEMOS_OWNER_PASSWORD },
821		},
822		{ method: 'GET', pathname: '/api/user/me' },
823		{ method: 'GET', pathname: '/api/memo' },
824		{ method: 'GET', pathname: '/api/memo', search: '?rowStatus=ARCHIVED' },
825		{ method: 'GET', pathname: '/api/tag' },
826		{ method: 'GET', pathname: '/api/shortcut' },
827		{
828			method: 'POST',
829			pathname: '/api/memo',
830			body: { content: 'Witnessed write from the frozen transcript. #evidence recorded.' },
831		},
832		{
833			method: 'PATCH',
834			pathname: '/api/memo/5',
835			body: { content: 'Edited in place. #evidence held.' },
836		},
837		{ method: 'POST', pathname: '/api/memo/5/organizer', body: { pinned: true } },
838		{ method: 'PATCH', pathname: '/api/memo/5', body: { rowStatus: 'ARCHIVED' } },
839		{ method: 'PATCH', pathname: '/api/memo/5', body: { rowStatus: 'NORMAL' } },
840		{ method: 'DELETE', pathname: '/api/memo/4' },
841		{ method: 'GET', pathname: '/api/tag' },
