843			method: 'POST',
844			pathname: '/api/shortcut',
845			body: {
846				title: 'Archive',
847				payload:
848					'[{"type":"TEXT","value":{"operator":"CONTAIN","value":"lane"},"relation":"AND"}]',
849			},
