156			path: relative(laneRoot, target.path),
157			offset: target.offset,
158			beforeSha256,
159			mutatedSha256,
160			afterRestoreSha256,
161			restoredByteIdentically: true,
162			restoredRun: 'pass',
163			restoredBehaviorDigest,
