537	async function staticInventory(staticRoot: string): Promise<StaticInventory> {
538		const entries: Array<{ path: string; sha256: string }> = [];
539		const visit = async (directory: string): Promise<void> => {
540			for (const entry of (await readdir(directory, { withFileTypes: true })).sort((a, b) =>
541				a.name.localeCompare(b.name),
542			)) {
543				const path = join(directory, entry.name);
544				if (entry.isSymbolicLink())
545					throw new Error('Witness production-static inventory rejects symbolic links');
546				if (entry.isDirectory()) await visit(path);
547				else if (entry.isFile())
548					entries.push({
549						path: relative(staticRoot, path),
550						sha256: sha256(await readFile(path)),
551					});
552				else throw new Error('Witness production-static inventory contains a non-file entry');
553			}
554		};
555		await visit(staticRoot);
556		entries.sort((a, b) => a.path.localeCompare(b.path));
557		const application = entries.find((entry) => entry.path === 'index.html');
558		if (application === undefined) throw new Error('Witness production-static index is absent');
559		return {
560			files: entries.length,
561			digest: sha256(canonicalize(entries)),
562			applicationSha256: application.sha256,
563			serviceWorkers: entries.filter(
564				(entry) => entry.path === 'sw.js' || entry.path === 'service-worker.js',
565			),
566		};
567	}
