569	function safeStaticPath(staticRoot: string, requestUrl: string): string | null {
570		let pathname: string;
571		try {
572			pathname = decodeURIComponent(parseURL(requestUrl).pathname || '/');
573		} catch {
574			return null;
575		}
576		if (
577			pathname.includes('\\') ||
578			pathname.includes('\0') ||
579			pathname.split('/').some((part) => part === '..')
580		)
581			return null;
582		let relativePath = normalize(pathname);
583		while (relativePath.startsWith('/')) relativePath = relativePath.slice(1);
584		const file = resolve(staticRoot, relativePath === '' ? 'index.html' : relativePath);
585		const fromRoot = relative(staticRoot, file);
586		if (fromRoot === '..' || fromRoot.startsWith('../') || isAbsolute(fromRoot)) return null;
587		return file;
588	}
