590	async function readStaticFile(file: string): Promise<{ file: string; body: Buffer } | null> {
591		const details = await lstat(file).catch(() => null);
592		if (details === null || details.isSymbolicLink()) return null;
593		const resolved = details.isDirectory() ? join(file, 'index.html') : file;
594		const resolvedDetails = await lstat(resolved).catch(() => null);
595		if (resolvedDetails === null || !resolvedDetails.isFile() || resolvedDetails.isSymbolicLink())
596			return null;
597		return { file: resolved, body: await readFile(resolved) };
598	}
