614	async function collectRequestBody(request: IncomingMessage): Promise<Buffer | null> {
615		const chunks: Buffer[] = [];
616		let bytes = 0;
617		for await (const chunk of request as AsyncIterable<Buffer | string>) {
618			const buffer = typeof chunk === 'string' ? Buffer.from(chunk, 'utf8') : chunk;
619			bytes += buffer.length;
620			if (bytes > MAX_API_REQUEST_BYTES) return null;
621			chunks.push(buffer);
622		}
623		return Buffer.concat(chunks);
624	}
