626	export async function startStaticServer(
627		staticRoot: string,
628		options: {
629			profile?: 'current-witness' | 'canonical-t060';
630			diagnosticEvent?: (
631				event: Omit<WitnessDifferentialEvent, 'sequence' | 'timestampMs'>,
632			) => void;
633			api?: (request: StaticServerApiRequest) => Promise<StaticServerApiResponse | null>;
634			upgrade?: (
635				request: IncomingMessage,
636				socket: Duplex,
637				head: Buffer,
638				record: WitnessSocketLedgerRecorder,
639			) => void | Promise<void>;
640		} = {},
641	): Promise<{
642		origin: string;
643		close(): Promise<void>;
644		assertClean(): void;
645		requests(): string[];
646		ledger(): StaticResponseLedgerEntry[];
647	}> {
648		const failures: string[] = [];
649		const requests: string[] = [];
650		const ledger: StaticResponseLedgerEntry[] = [];
651		const server: Server = createServer((request, response) => {
652			void (async () => {
653				const parsedRequest = parseURL(request.url ?? '/');
654				const pathname = parsedRequest.pathname || '/';
655				const urlPath = `${pathname}${parsedRequest.search ?? ''}`;
656				options.diagnosticEvent?.({
657					source: 'static-server',
658					phase: 'start',
659					urlPath,
660					detail: {},
661				});
662				request.once('aborted', () =>
663					options.diagnosticEvent?.({
664						source: 'static-server',
665						phase: 'abort',
666						urlPath,
667						detail: {},
668					}),
669				);
670				requests.push(pathname);
671				const complete = (
672					status: number,
673					mime: string,
674					body: Buffer,
675					resolvedFile: string | null,
676				): void => {
677					response.once('finish', () => {
678						ledger.push({
679							method: request.method ?? 'GET',
680							pathname,
681							query: parsedRequest.search ?? '',
682							destination:
683								typeof request.headers['sec-fetch-dest'] === 'string'
684									? request.headers['sec-fetch-dest']
685									: '',
686							resolvedFile,
687							status,
688							mime,
689							bytes: body.length,
690							sha256: sha256(body),
691						});
692						options.diagnosticEvent?.({
693							source: 'static-server',
694							phase: 'finish',
695							urlPath,
696							detail: { status, bytes: body.length, sha256: sha256(body), mime },
697						});
698					});
699					response.writeHead(status, {
700						...(options.profile === 'canonical-t060'
701							? {}
702							: { 'cache-control': 'no-store' }),
703						'content-type':
704							options.profile === 'canonical-t060' &&
705							(mime === 'text/html' || mime === 'text/javascript')
706								? `${mime}; charset=utf-8`
707								: mime,
708					});
709					response.end(body);
710				};
711				if (options.api !== undefined) {
712					const body = await collectRequestBody(request);
713					if (body === null) {
714						complete(413, 'text/plain', Buffer.from('payload too large'), null);
715						return;
716					}
717					const fulfilled = await options.api({
718						method: request.method ?? 'GET',
719						pathname,
720						search: parsedRequest.search ?? '',
721						body,
722					});
723					if (fulfilled !== null) {
724						complete(fulfilled.status, fulfilled.contentType, fulfilled.body, null);
725						return;
726					}
727				}
728				const requestedFile = safeStaticPath(staticRoot, request.url ?? '/');
729				if (requestedFile === null) {
730					complete(400, 'text/plain', Buffer.from('invalid path'), null);
731					return;
732				}
733				let result = await readStaticFile(requestedFile);
734				if (result === null && request.headers['sec-fetch-dest'] === 'document')
735					result = await readStaticFile(join(staticRoot, 'index.html'));
736				if (result === null) {
737					complete(404, 'text/plain', Buffer.from('not found'), null);
738					return;
739				}
740				complete(
741					200,
742					CONTENT_TYPES[extname(result.file)] ?? 'application/octet-stream',
743					result.body,
744					relative(staticRoot, result.file),
745				);
746			})().catch((error: unknown) => {
747				failures.push(error instanceof Error ? error.message : String(error));
748				if (!response.headersSent) response.writeHead(500, { 'content-type': 'text/plain' });
749				response.end('static server failure');
750			});
751		});
752		server.requestTimeout = 15_000;
753		server.headersTimeout = 10_000;
754		if (options.upgrade !== undefined) {
755			const upgrade = options.upgrade;
756			const recordSocket = (record: WitnessSocketLedgerRecord): void => {
757				ledger.push({
758					method: record.method,
759					pathname: record.pathname,
760					query: record.query,
761					destination: 'websocket',
762					resolvedFile: null,
763					status: record.status,
764					mime: record.mime,
765					bytes: record.body.length,
766					sha256: sha256(record.body),
767					socket: record.socket,
768				});
769			};
770			server.on('upgrade', (request, socket, head) => {
771				void (async () => {
772					await upgrade(request, socket, head, recordSocket);
773				})().catch((error: unknown) => {
774					failures.push(error instanceof Error ? error.message : String(error));
775					socket.destroy();
776				});
777			});
778		}
779		await new Promise<void>((resolveListen, rejectListen) => {
780			server.once('error', rejectListen);
781			server.listen(0, '127.0.0.1', () => {
782				server.off('error', rejectListen);
783				resolveListen();
784			});
785		});
786		const address = server.address();
787		if (address === null || typeof address === 'string') throw new Error('static origin is absent');
788		const origin = stringifyParsedURL({
789			protocol: 'http:',
790			host: `127.0.0.1:${(address as AddressInfo).port}`,
791		});
792		return {
793			origin,
794			close: async () =>
795				void (await new Promise<void>((resolveClose, rejectClose) => {
796					server.close((error) =>
797						error === undefined ? resolveClose() : rejectClose(error),
798					);
799				})),
800			assertClean: () => {
801				if (failures.length > 0)
802					throw new Error(`Witness production-static server failed: ${failures.join('; ')}`);
803			},
804			requests: () => [...requests],
805			ledger: () => structuredClone(ledger),
806		};
807	}
